CREATE TABLE IF NOT EXISTS users (id VARCHAR(32) PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS companies (id VARCHAR(32) PRIMARY KEY,normalized_name VARCHAR(255) NOT NULL UNIQUE,body JSON NOT NULL);
CREATE TABLE IF NOT EXISTS sources (id VARCHAR(32) PRIMARY KEY,body JSON NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id VARCHAR(32) PRIMARY KEY,company_id VARCHAR(32) NOT NULL,fingerprint CHAR(64) NOT NULL UNIQUE,body JSON NOT NULL,FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE IF NOT EXISTS postings (id VARCHAR(32) PRIMARY KEY,job_id VARCHAR(32) NOT NULL,source_id VARCHAR(32) NOT NULL,source_key CHAR(64) NOT NULL UNIQUE,body JSON NOT NULL,FOREIGN KEY(job_id) REFERENCES jobs(id),FOREIGN KEY(source_id) REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS observations (id VARCHAR(32) PRIMARY KEY,posting_id VARCHAR(32) NOT NULL,job_id VARCHAR(32) NOT NULL,observed_at DATETIME(6) NOT NULL,body JSON NOT NULL,INDEX(job_id,observed_at),FOREIGN KEY(posting_id) REFERENCES postings(id));
CREATE TABLE IF NOT EXISTS analysis_results (observation_id VARCHAR(32) NOT NULL,analysis_version VARCHAR(64) NOT NULL,created_at DATETIME(6) NOT NULL,PRIMARY KEY(observation_id,analysis_version),FOREIGN KEY(observation_id) REFERENCES observations(id));
CREATE TABLE IF NOT EXISTS evidence (id VARCHAR(32) PRIMARY KEY,observation_id VARCHAR(32) NOT NULL,job_id VARCHAR(32) NOT NULL,body JSON NOT NULL,INDEX(job_id),FOREIGN KEY(observation_id) REFERENCES observations(id));
CREATE TABLE IF NOT EXISTS assessments (id VARCHAR(32) PRIMARY KEY,job_id VARCHAR(32) NOT NULL,assessed_at DATETIME(6) NOT NULL,body JSON NOT NULL,INDEX(job_id,assessed_at),FOREIGN KEY(job_id) REFERENCES jobs(id));
CREATE TABLE IF NOT EXISTS changes (id VARCHAR(32) PRIMARY KEY,job_id VARCHAR(32) NOT NULL,change_key VARCHAR(160) NOT NULL UNIQUE,body JSON NOT NULL,FOREIGN KEY(job_id) REFERENCES jobs(id));
CREATE TABLE IF NOT EXISTS profiles (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,body JSON NOT NULL,UNIQUE(user_id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS eligibilities (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,job_id VARCHAR(32) NOT NULL,body JSON NOT NULL,INDEX(user_id,job_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(job_id) REFERENCES jobs(id));
CREATE TABLE IF NOT EXISTS rankings (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,job_id VARCHAR(32) NOT NULL,body JSON NOT NULL,UNIQUE(user_id,job_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(job_id) REFERENCES jobs(id));
CREATE TABLE IF NOT EXISTS applications (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,job_id VARCHAR(32) NOT NULL,version INT NOT NULL,body JSON NOT NULL,UNIQUE(user_id,job_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(job_id) REFERENCES jobs(id));
CREATE TABLE IF NOT EXISTS application_events (id VARCHAR(32) PRIMARY KEY,application_id VARCHAR(32) NOT NULL,body JSON NOT NULL,FOREIGN KEY(application_id) REFERENCES applications(id));
CREATE TABLE IF NOT EXISTS interviews (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,application_id VARCHAR(32) NOT NULL,body JSON NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(application_id) REFERENCES applications(id));
CREATE TABLE IF NOT EXISTS reviews (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,interview_id VARCHAR(32) NOT NULL,body JSON NOT NULL,UNIQUE(interview_id),FOREIGN KEY(interview_id) REFERENCES interviews(id));
CREATE TABLE IF NOT EXISTS weak_topics (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,topic VARCHAR(120) NOT NULL,body JSON NOT NULL,UNIQUE(user_id,topic),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS projects (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,body JSON NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS project_facts (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,project_id VARCHAR(32) NOT NULL,body JSON NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS documents (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,body JSON NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS chunks (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,document_id VARCHAR(32) NOT NULL,body JSON NOT NULL,FOREIGN KEY(document_id) REFERENCES documents(id));
CREATE TABLE IF NOT EXISTS outbox (id VARCHAR(32) PRIMARY KEY,body JSON NOT NULL,sent BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME(6) NOT NULL,INDEX(sent,created_at));
CREATE TABLE IF NOT EXISTS completed_tasks (id VARCHAR(100) PRIMARY KEY,completed_at DATETIME(6) NOT NULL);
CREATE TABLE IF NOT EXISTS action_receipts (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL,result JSON NOT NULL,created_at DATETIME(6) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
